// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(address potentialCeo, uint256 drugs) public {
        vm.assume(potentialCeo != address(0));
        drugs = bound(drugs, 1, 1e30);

        vm.deal(potentialCeo, 1 ether);

        vm.prank(potentialCeo);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok);

        vm.prank(potentialCeo);
        c.seedMarket{value: 0}(drugs);

        assertTrue(c.ceoAddress() == potentialCeo && c.initialized() == true);
    }
}
